378	/*
379	 * A blocked process can only be resumed in user mode, so waitpid cannot
380	 * simply continue where it left off.  Instead the caller is blocked on the
381	 * child's wait list and `sepc` is rewound onto the `ecall`, so once the child
382	 * exits the system call is executed again -- this time finding the child
383	 * gone (or a zombie ready to be reaped).  The return value has to be `pid`
384	 * in that case because handle_syscall() writes it back into a0, which is the
385	 * very argument the retried `ecall` will pick up.
386	 */
387	int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
388	{
389	    disable_preempt();
390	
391	    pcb_t *child = NULL;
392	    for (int i = 0; i < NUM_MAX_TASK; i++) {
393	        if (pcb[i].pid == pid) {
394	            child = &pcb[i];
395	            break;
396	        }
397	    }
398	
399	    if (child == NULL) {
400	        /* already gone and cleaned up */
401	        enable_preempt();
402	        return 0;
403	    }
404	
405	    if (child->status == TASK_ZOMBIE || child->status == TASK_EXITED) {
406	        /* reap it: release the kernel stack and free the pcb slot */
407	        free_user_page(kva2pa(child->kernel_stack_base - PAGE_SIZE));
408	        list_del(&child->list);
409	        child->status = TASK_EXITED;
410	        child->pid = -1;
411	        enable_preempt();
412	        return 1;
413	    }
414	
415	    /* still alive: sleep on it and retry the system call when woken up */
416	    regs->sepc = regs->sepc - 4;
417	    do_block(&current_running[cpu_id]->list, &child->wait_list);
418	    scheduler();
419	
420	    enable_preempt();
421	    return pid;
422	}
