592	// block the pcb task into the block queue
593	void do_block(list_node_t *pcb_node, list_head *queue)
594	{
595	    list_del(pcb_node);
596	    list_add_tail(pcb_node, queue);
597	    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
598	}
599	
600	// unblock the `pcb` from the block queue
601	void do_unblock(list_node_t *pcb_node)
602	{
603	    list_del(pcb_node);
604	    list_add_tail(pcb_node, &ready_queue);
605	    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
606	    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
607	}
608	
609	/*
610	 * Pick the ready task with the highest effective priority that is allowed to
611	 * run on this hart.  The effective priority is the static priority plus an
612	 * ageing bonus of one point per scheduling tick already spent waiting, so a
613	 * low priority task cannot starve.  Ties go to the task that has been in the
614	 * queue longest, which keeps equal priorities round-robin.
615	 */
616	list_node_t* max_priority_node(void)
617	{
618	    list_node_t *node;
619	    list_node_t *max_node = NULL;
620	    uint64_t max_priority = 0;
621	    uint64_t current_tick = get_ticks();
622	
623	    for (node = ready_queue.next; node != &ready_queue; node = node->next) {
624	        pcb_t *task = list_entry(node, pcb_t, list);
625	        uint64_t waited_tick = 0;
626	        uint64_t priority;
627	
628	        /* cpu affinity */
629	        if (!(task->mask & (1UL << cpu_id))) {
630	            continue;
631	        }
632	
633	        if (current_tick > task->ready_tick) {
634	            waited_tick = current_tick - task->ready_tick;
635	        }
636	        priority = (uint64_t)task->priority;
637	        if (timer_interval != 0) {
638	            priority += waited_tick / timer_interval;
639	        }
640	
641	        if (max_node == NULL || priority > max_priority) {
642	            max_node = node;
643	            max_priority = priority;
644	        }
645	    }
646	
647	    return max_node;
648	}

