13	void mthread_barrier_wait(mthread_barrier_t *barrier)
14	{
15	    sys_binsem_op(barrier->binsem_id, BINSEM_OP_LOCK);
16	    barrier->reached = barrier->reached + 1;
17	    if((barrier->reached) == (barrier->count)){
18	        barrier->reached = 0;
19	        sys_futex_wakeup((unsigned long*)barrier, barrier->count);    
20	        sys_binsem_op(barrier->binsem_id, BINSEM_OP_UNLOCK);                   
21	    }
22	    else{ 
23	        sys_futex_wait((unsigned long*)barrier, barrier->binsem_id);
24	    }
25	}
26	void mthread_barrier_destroy(mthread_barrier_t *barrier)
27	{
28	    barrier->count = -1;
29	    barrier->reached = 0;
30	}
