18	// a simple hash function
19	static int futex_hash(uint64_t x)
20	{
21	    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
22	    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
23	    x = x ^ (x >> 31);
24	    return x % FUTEX_BUCKETS;
25	}
