27	static futex_node_t* get_node(volatile uint64_t *val_addr, int create)
28	{
29	    int key = futex_hash((uint64_t)val_addr);
30	    list_node_t *head = &futex_buckets[key];
31	    for (list_node_t *p = head->next; p != head; p = p->next) {
32	        futex_node_t *node = list_entry(p, futex_node_t, list);
33	        if (node->futex_key == (uint64_t)val_addr) {
34	            return node;
35	        }
36	    }
37	
38	    if (create) {
39	        futex_node_t *node = (futex_node_t*)pa2kva((uintptr_t)kmalloc(sizeof(futex_node_t)));
40	        node->futex_key = (uint64_t)val_addr;
41	        init_list_head(&node->block_queue);
42	        list_add_tail(&node->list, &futex_buckets[key]);
43	        return node;
44	    }
45	
46	    return NULL;
47	}
