49	void futex_wait(volatile uint64_t *val_addr, int binsem_id)
50	{
51	    disable_preempt();
52	
53	    futex_node_t *node = get_node(val_addr, 1);
54	    assert(node != NULL);
55	    do_block(&current_running[cpu_id]->list, &node->block_queue);
56	    binsem_op(binsem_id, BINSEM_OP_UNLOCK);
57	    scheduler(); 
58	
59	    enable_preempt();
60	}
61	
62	void futex_wakeup(volatile uint64_t *val_addr, int num_wakeup)
63	{
64	    disable_preempt();
65	    futex_node_t *node = get_node(val_addr, 0);
66	
67	    if (node != NULL) {
68	        for (int i = 0; i < num_wakeup; ++i) {
69	            if (list_empty(&node->block_queue)) break;
70	
71	            do_unblock(node->block_queue.next);
72	        }
73	    }
74	
75	    scheduler();
76	    enable_preempt();
77	}

