/* Give up every binary semaphore `task` still holds and hand each of them to
 * the next waiter, so that nobody stays blocked on a dead process. */
static void release_binsem(pcb_t *task)
{
    while (task->binsem_num > 0) {
        int id = task->binsem_id[--task->binsem_num];
        binsem_node_t *node = &binsem_nodes[id];

        node->sem++;
        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
            list_node_t *heir_node = node->block_queue.next;
            pcb_t *heir = list_entry(heir_node, pcb_t, list);
            heir->binsem_id[heir->binsem_num++] = id;
            do_unblock(heir_node);
        }
    }
}

/*
 * A task that dies while queued on a binary semaphore has already spent the
 * `sem--` of its pending acquire.  Give that count back, otherwise the next
 * release would believe somebody is still waiting and hand the lock to the
 * head of an empty queue.
 */
static void abandon_binsem_wait(pcb_t *task)
{
    for (int i = 0; i < BINSEM_NUMBER; i++) {
        binsem_node_t *node = &binsem_nodes[i];
        list_node_t *p;
        for (p = node->block_queue.next; p != &node->block_queue; p = p->next) {
            if (p == &task->list) {
                list_del(p);
                node->sem++;
                return;
            }
        }
    }
}

